using FluentAssertions;
using FluentValidation;
using Moq;
using SrBackendMillon.Application.Abstractions;
using SrBackendMillon.Application.DTOs;
using SrBackendMillon.Application.Services;
using SrBackendMillon.Domain.Entities;
using SrBackendMillon.Infrastructure.Repositories;

namespace SrBackendMillon.Test
{
    public class PropertyServiceTest
    {
        private Mock<IPropertyRepository> _propertyRepositoryMock = null!;
        private Mock<IImageRepository> _imageRepositoryMock = null!;
        private Mock<IValidator<PropertyCreateDto>> _validatorMock = null!;
        private IPropertyService _propertyService = null!;
        private IImageService _imageService = null!;

        [SetUp]
        public void Setup()
        {
            _propertyRepositoryMock = new Mock<IPropertyRepository>();
            _imageRepositoryMock = new Mock<IImageRepository>();
            _validatorMock = new Mock<IValidator<PropertyCreateDto>>();

            _validatorMock.Setup(v => v.ValidateAsync(It.IsAny<PropertyCreateDto>(), It.IsAny<CancellationToken>()))
                .ReturnsAsync(new FluentValidation.Results.ValidationResult());

            _propertyService = new PropertyService(_propertyRepositoryMock.Object,
                _imageRepositoryMock.Object,
                _validatorMock.Object);

            _imageService = new PropertyService(_propertyRepositoryMock.Object, _imageRepositoryMock.Object, _validatorMock.Object);
        }

        [Test]
        public async Task CreateAsync_ShouldReturnProperty_WhenValid()
        {
            // Arrange
            var dto = new PropertyCreateDto(
                Name: "Juan David Layton",
                Address: "Calle 123",
                Price: 250000,
                ImageId: ""
            );

            var property = new Property(
                idOwner: new Guid().ToString(),
                name: dto.Name,
                address: dto.Address,
                price: dto.Price,
                imageId: dto.ImageId
            );

            _propertyRepositoryMock
                .Setup(r => r.InsertAsync(It.IsAny<Property>(), It.IsAny<CancellationToken>()))
                .Returns(Task.CompletedTask);

            // Act
            var result = await _propertyService.CreatePropertyAsync(dto);

            // Assert
            result.Should().NotBeNull();
            result.Name.Should().Be("Juan David Layton");

            _propertyRepositoryMock.Verify(r => r.InsertAsync(It.IsAny<Property>(), It.IsAny<CancellationToken>()), Times.Once);
            //_validatorMock.Verify(v => v.ValidateAsync(It.IsAny<PropertyCreateDto>(), It.IsAny<CancellationToken>()), Times.Once);
            //_validatorMock.Verify(v =>
            //        v.ValidateAsync(It.Is<PropertyCreateDto>(x =>
            //            x.Name == "Juan David Layton" &&
            //            x.Address == "Calle 123" &&
            //            x.Price == 250000
            //        ), It.IsAny<CancellationToken>()),
            //        Times.Once
            //    );
        }

        [Test]
        public async Task GetByIdAsync_Should_Return_Property_When_Found()
        {
            // Arrange
            var property = new Property("68b32c554457126eccfecad4", "Casa Bonita", "Calle 123", 200000, "img001");

            _propertyRepositoryMock
                .Setup(r => r.GetByIdAsync("68b32c554457126eccfecad4", It.IsAny<CancellationToken>()))
                .ReturnsAsync(property);

            // Act
            var result = await _propertyService.GetPropertyByIdAsync("68b32c554457126eccfecad4");

            // Assert
            Assert.That(result, Is.Not.Null);
            Assert.That(result.Name, Is.EqualTo("Casa Bonita"));
            _propertyRepositoryMock.Verify(r => r.GetByIdAsync("68b32c554457126eccfecad4", It.IsAny<CancellationToken>()), Times.Once);
        }

        [Test]
        public async Task GetByIdAsync_Should_Return_Null_When_Not_Found()
        {
            // Arrange
            _propertyRepositoryMock
                .Setup(r => r.GetByIdAsync("99", It.IsAny<CancellationToken>()))
                .ReturnsAsync((Property?)null);

            // Act
            var result = await _propertyService.GetPropertyByIdAsync("99");

            // Assert
            Assert.That(result, Is.Null);
            _propertyRepositoryMock.Verify(r => r.GetByIdAsync("99", It.IsAny<CancellationToken>()), Times.Once);
        }

        [Test]
        public void CreateAsync_ShouldThrow_WhenValidationFails()
        {
            // Arrange
            var dto = new PropertyCreateDto(
                Name: "",
                Address: "Calle 123",
                Price: 0,
                ImageId: "img001"
            );

            _validatorMock
                .Setup(v => v.ValidateAsync(dto, It.IsAny<CancellationToken>()))
                .ReturnsAsync(new FluentValidation.Results.ValidationResult(new[]
                {
            new FluentValidation.Results.ValidationFailure("Name", "Name is required")
                }));

            // Act
            Func<Task> act = async () => await _propertyService.CreatePropertyAsync(dto);

            // Assert
            act.Should().ThrowAsync<ValidationException>();
            _propertyRepositoryMock.Verify(r => r.InsertAsync(It.IsAny<Property>(), It.IsAny<CancellationToken>()), Times.Never);
        }

        [Test]
        public async Task GetByIdAsync_ShouldReturnNull_WhenNotFound()
        {
            // Arrange
            _propertyRepositoryMock
                .Setup(r => r.GetByIdAsync("notfound", It.IsAny<CancellationToken>()))
                .ReturnsAsync((Property?)null);

            // Act
            var result = await _propertyService.GetPropertyByIdAsync("notfound");

            // Assert
            result.Should().BeNull();
        }

        [Test]
        public async Task GetAllAsync_ShouldReturnListOfProperties()
        {
            // Arrange
            var properties = new List<Property>
    {
        new Property("1", "Casa Bonita", "Calle 123", 200000, "img001"),
        new Property("2", "Apartamento Centro", "Calle 456", 300000, "img002")
    };

            _propertyRepositoryMock
                .Setup(r => r.GetAllAsync(It.IsAny<CancellationToken>()))
                .ReturnsAsync(properties);

            // Act
            var result = await _propertyService.GetAllPropertiesAsync();

            // Assert
            result.Should().NotBeEmpty();
            result.Should().HaveCount(2);
            result.First().Name.Should().Be("Casa Bonita");
        }

        [Test]
        public async Task GetImageAsync_ShouldReturnImage_WhenExists()
        {
            // Arrange
            var imageId = "68b32c514457126eccfecad2";
            var imageData = new byte[] { 1, 2, 3, 4 };

            _imageRepositoryMock
                .Setup(r => r.GetImageAsync(imageId, It.IsAny<CancellationToken>()))
                .ReturnsAsync(imageData);

            // Act
            var result = await _imageService.GetImageAsync(imageId);

            // Assert
            result.Should().NotBeNull();
            result.Should().BeEquivalentTo(imageData);
        }



    }
}
